    /// What the catalogue binds a token path as, for the failure that says a cell is of another kind.
    static func kind(of path: String) -> String? {
        if color[path] != nil { return "a colour" }
        if dimension[path] != nil { return "a dimension" }
        if number[path] != nil { return "a number" }
        if typography[path] != nil { return "a type role" }
        if shadow[path] != nil { return "a shadow" }
        if gradient[path] != nil { return "a gradient" }
        if spring[path] != nil { return "a spring" }
        if easing[path] != nil { return "an easing curve" }
        if stroke[path] != nil { return "a stroke style" }
        if flag[path] != nil { return "a flag" }
